import React from 'react';
import { motion } from 'framer-motion';
import { Palette } from 'lucide-react';

const themes = [
    { id: 'cyber', name: 'Cyber', color: '#64ffda' },
    { id: 'sunset', name: 'Sunset', color: '#ff7e5f' },
    { id: 'purple', name: 'Purple', color: '#a855f7' },
    { id: 'gold', name: 'Gold', color: '#fbbf24' },
];

function ThemeToggle({ currentTheme, setTheme }) {
    return (
        <div className="theme-toggle" role="group" aria-label="Theme selector">
            <Palette size={18} className="theme-icon" aria-hidden="true" />
            <div className="theme-options">
                {themes.map((t) => (
                    <motion.button
                        key={t.id}
                        whileHover={{ scale: 1.2 }}
                        whileTap={{ scale: 0.9 }}
                        className={`theme-dot ${currentTheme === t.id ? 'active' : ''}`}
                        style={{ backgroundColor: t.color }}
                        onClick={() => setTheme(t.id)}
                        title={`Set ${t.name} theme`}
                        aria-pressed={currentTheme === t.id}
                    />
                ))}
            </div>
        </div>
    );
}

export default ThemeToggle;
